// Checks every translation vocabulary against the English source (plan D4).
//
// src/locale/messages.json is generated by `ng extract-i18n` from the labels in
// the code (i18n="@@label", $localize`:@@label:…`). Each messages.<locale>.json
// must have exactly the same labels, and each translation exactly the same
// placeholders ({$INTERPOLATION}, {$START_TAG_SPAN}, …) as its source text.
//
// The build's i18nMissingTranslation: "error" already fails on a missing label;
// this also catches stale labels and dropped or invented placeholders, which
// the build accepts and renders wrong.
import { readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';

const DIR = 'src/locale';
const load = async (file) => JSON.parse(await readFile(join(DIR, file), 'utf8'));
const placeholders = (text) => (text.match(/\{\$[A-Za-z0-9_]+\}/g) ?? []).sort().join(' ');

const source = (await load('messages.json')).translations;
const files = (await readdir(DIR)).filter((f) => /^messages\.[\w-]+\.json$/.test(f));
const problems = [];

for (const file of files) {
  const { locale, translations } = await load(file);
  for (const id of Object.keys(source)) {
    if (!(id in translations)) {
      problems.push(`${file}: missing "${id}"`);
    } else if (placeholders(source[id]) !== placeholders(translations[id])) {
      problems.push(
        `${file}: "${id}" placeholders [${placeholders(translations[id])}] ≠ source [${placeholders(source[id])}]`,
      );
    } else if (!translations[id].trim()) {
      problems.push(`${file}: "${id}" is empty`);
    }
  }
  for (const id of Object.keys(translations)) {
    if (!(id in source)) problems.push(`${file}: "${id}" is not in the source (stale label?)`);
  }
  if (!locale) problems.push(`${file}: no "locale" field`);
}

if (problems.length) {
  console.error(problems.join('\n'));
  process.exit(1);
}
console.log(`vocabulary: ${Object.keys(source).length} labels, ${files.join(', ')} complete`);
